  });
  PanelGroup.displayName = "MockPanelGroup";
  // Record each panel's lifecycle callbacks so a test can fire the ones the
  // real library fires on its own, such as the initial-layout collapse.
  const Panel = ({
    children,
    id,
    onCollapse,
