  }: {
    children?: ReactNode;
    id?: string;
    onCollapse?: () => void;
    onResize?: (size: number) => void;
  }) => {
    if (id !== undefined) panelCallbacks.set(id, { onCollapse, onResize });
    return (
      <div data-testid="workspace-panel" data-panel-id={id}>
        {children}
