            <LocationProbe />
            <CommandCenterStateProbe />
            <HistoryForwardNav />
            {options.externalTo !== undefined ? (
              <ExternalNav to={options.externalTo} />
            ) : null}
          </MemoryRouter>
        </QueryClientProvider>
      </JotaiProvider>
    </TooltipProvider>,
  );
  return store;
}

